<script setup lang="ts">
import {ref,onMounted} from 'vue'
import client from '@/api/client'
import {ElMessage} from 'element-plus'
type Policy={enabled:boolean;kind:string;rateBps:number;capCents:number;waitDays:number;minWithdrawCents:number;couponId:number;revision:number}
type Withdrawal={id:number;userId:string;amountCents:number;holderName:string;bankName:string;accountNumber:string;status:string;transferReference:string;note:string}
type Reward={id:number;creatorId:string;orderNo:string;designId:number;kind:string;amountCents:number;status:string;reason:string}
const policy=ref<Policy>(),data=ref<{rewards:Reward[];withdrawals:Withdrawal[];total:number;withdrawalTotal:number}>(),page=ref(1),busy=ref(false),error=ref('')
const target=ref<Withdrawal>(),action=ref(''),note=ref(''),reference=ref(''),dialog=ref(false)
const labels:Record<string,string>={review_required:'退款待人工核对',pending:'待处理',settled:'已结算',cancelled:'已撤销',excluded:'不参与奖励',approved:'审核通过',processing:'打款处理中',paid:'已打款',rejected:'已拒绝',failed:'打款失败'}
async function load(){busy.value=true;try{const [p,d]=await Promise.all([client.get<Policy>('/admin/diy/reward-policy'),client.get<NonNullable<typeof data.value>>('/admin/diy/creator-wallet?page='+page.value)]);policy.value=p;data.value=d;error.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
async function run(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;try{await fn();ElMessage.success('操作成功');dialog.value=false;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
function review(row:Withdrawal,a:string){target.value=row;action.value=a;note.value='';reference.value='';dialog.value=true}
const actionLabels:Record<string,string>={approve:'通过审核',reject:'拒绝并释放冻结',processing:'进入人工打款',paid:'登记已打款',failed:'确认未付款并退回冻结'}
onMounted(load)
</script>
<template><section><h1>DIY 创作奖励与提现</h1><el-alert title="现金创作收益与消费余额分账。仅真实成交参与奖励，模拟支付和自购排除。人工银行转账：审核通过不会自动转账。" type="info" :closable="false"/><el-alert v-if="error" :title="error" type="error"/>
<el-card v-if="policy" style="margin:20px 0"><h2>新订单奖励规则</h2><el-form label-width="140px"><el-form-item label="启用奖励"><el-switch v-model="policy.enabled"/></el-form-item><el-form-item label="奖励形式"><el-select v-model="policy.kind"><el-option label="现金创作收益（可提现）" value="cash"/><el-option label="消费余额（不可提现）" value="balance"/><el-option label="优惠券" value="coupon"/></el-select></el-form-item><el-form-item v-if="policy.kind!=='coupon'" label="比例（万分比）"><el-input-number v-model="policy.rateBps" :min="0" :max="10000"/><span>500 = 5%，基于材料实付，不含附加服务</span></el-form-item><el-form-item v-if="policy.kind!=='coupon'" label="单笔上限（分）"><el-input-number v-model="policy.capCents" :min="1" :max="1000000"/></el-form-item><el-form-item v-if="policy.kind==='coupon'" label="优惠券模板 ID"><el-input-number v-model="policy.couponId" :min="1"/><span>使用营销管理中的有效优惠券；按订单发独立券，扣减模板库存。过期或不足会保留待结算。</span></el-form-item><el-form-item label="完成后等待天数"><el-input-number v-model="policy.waitDays" :min="7" :max="365"/></el-form-item><el-form-item label="最低提现（分）"><el-input-number v-model="policy.minWithdrawCents" :min="1" :max="1000000"/></el-form-item><el-button type="primary" :disabled="busy" @click="run(()=>client.put('/admin/diy/reward-policy',policy))">保存新订单规则</el-button><p>不追溯上线前订单，不改变已有订单的奖励快照。现金以人民币结算，平台提现手续费为 0。</p></el-form></el-card>
<div><el-button :disabled="busy" @click="load">刷新</el-button><el-button :disabled="busy" @click="run(()=>client.post('/admin/diy/rewards/settle'))">重试到期结算</el-button><span>后台每分钟自动核查，重试不会重复发奖。</span></div>
<h2>提现审核与人工打款</h2><el-table :data="data?.withdrawals" v-loading="busy"><el-table-column prop="id" label="申请号" width="85"/><el-table-column prop="userId" label="用户" width="85"/><el-table-column label="金额"><template #default="{row}">¥{{(row.amountCents/100).toFixed(2)}}</template></el-table-column><el-table-column label="收款资料"><template #default="{row}">{{row.holderName}} · {{row.bankName}}<br/>{{row.accountNumber}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{labels[row.status]||row.status}}<br/>{{row.note}}<br/>{{row.transferReference}}</template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><template v-if="row.status==='pending'"><el-button :disabled="busy" @click="review(row,'approve')">审核通过</el-button><el-button :disabled="busy" @click="review(row,'reject')">拒绝</el-button></template><template v-if="row.status==='approved'"><el-button :disabled="busy" @click="review(row,'processing')">进入打款</el-button><el-button :disabled="busy" @click="review(row,'reject')">退回</el-button></template><template v-if="row.status==='processing'"><el-button :disabled="busy" @click="review(row,'paid')">登记已打款</el-button><el-button :disabled="busy" @click="review(row,'failed')">确认失败</el-button></template></template></el-table-column></el-table>
<h2>创作奖励明细</h2><el-table :data="data?.rewards"><el-table-column prop="creatorId" label="作者"/><el-table-column prop="orderNo" label="来源订单"/><el-table-column prop="designId" label="设计"/><el-table-column label="奖励"><template #default="{row}">{{row.kind==='cash'?'现金':row.kind==='balance'?'消费余额':'优惠券'}} {{row.kind==='coupon'?'1 张':'¥'+(row.amountCents/100).toFixed(2)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{labels[row.status]||row.status}} · {{row.reason}}</template></el-table-column></el-table>
<el-pagination v-if="data" v-model:current-page="page" :page-size="20" :total="Math.max(data.total,data.withdrawalTotal)" layout="prev,pager,next" @current-change="load"/>
<el-dialog v-model="dialog" :title="actionLabels[action]" width="min(560px, 94vw)" append-to-body :close-on-click-modal="!busy"><p>申请 #{{target?.id}} · ¥{{((target?.amountCents||0)/100).toFixed(2)}} · {{target?.holderName}}</p><el-alert v-if="action==='paid'" title="仅在实际转账成功并完成对账后登记。此操作不会调用银行接口。" type="warning" :closable="false"/><el-alert v-if="action==='failed'" title="必须先核实银行未付款；结果未知时保持处理中，禁止重新付款。" type="warning" :closable="false"/><el-input v-if="action==='paid'" v-model="reference" placeholder="银行唯一转账流水（必填）" maxlength="128"/><el-input v-model="note" type="textarea" placeholder="审核／对账依据或失败原因；打款成功、失败和拒绝时必填" maxlength="500"/><template #footer><el-button :disabled="busy" @click="dialog=false">取消</el-button><el-button type="primary" :disabled="busy || (['paid','failed','reject'].includes(action)&&!note.trim()) || (action==='paid'&&!reference.trim())" @click="run(()=>client.post('/admin/diy/creator-withdrawals/'+target?.id+'/action',{action,reference,note}))">确认{{actionLabels[action]}}</el-button></template></el-dialog>
</section></template>
